select  from cbs.t_contractor


        open_status = false
        open_status = true


        and coop_status = #{coop}


        and approve_status = #{status}


        and (name like concat('%', #{kw}, '%') or uscc like concat('%', #{kw}, '%'))


        and ctype = #{ctype}


order by create_time desc
limit #{limit} offset #{offset}

select count(*)
from cbs.t_contractor


        open_status = false
        open_status = true


        and coop_status = #{coop}


        and approve_status = #{status}


        and (name like concat('%', #{kw}, '%') or uscc like concat('%', #{kw}, '%'))


        and ctype = #{ctype}

select count(*) from cbs.t_contractor
where open_status = true and uscc = #{uscc}
  and contractor_id <> coalesce(#{excludeId}, '')

mapper.update:
update cbs.t_contractor
name = #{c.name}, uscc = #{c.uscc}, ctype = #{c.ctype}, legal_person = #{c.legal_person}, legal_phone = #{c.legal_phone}, safety_person = #{c.safety_person}, safety_phone = #{c.safety_phone}, register_address = #{c.register_address}, register_capital = #{c.register_capital}, deposit = #{c.deposit}, login_account = #{c.login_account}, phone = #{c.phone}, id_card = #{c.id_card}, post_name = #{c.post_name}, role_name = #{c.role_name}, coop_status = #{c.coop_status},
where contractor_id = #{c.contractor_id}

update cbs.t_contractor
set approve_status = #{status},
    reject_reason = #{reason}
where contractor_id = #{id}

update cbs.t_contractor
set deposit = coalesce(deposit, 0) + #{delta}
where contractor_id = #{id}
